class StrategyContext {
  constructor(strategy) {
    this.strategy = strategy;
  }
  execute(amount) {
    return this.strategy(amount);
  }
}
const strategy = (value) => `Processed ${value}`;
const context = new StrategyContext(strategy);
console.log(context.execute(100));

const debounce = (fn, wait) => {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn(...args), wait);
  };
};
const throttled = debounce((value) => console.log('invoke', value), 200);
throttled('event');

const proxy = new Proxy({ count: 0 }, {
  get(target, prop) {
    console.log('access', prop);
    return target[prop];
  }
});
proxy.count = 1;
console.log(proxy.count);

const asyncWork = async (value) => {
  await new Promise((r) => setTimeout(r, 50));
  return value * 2;
};
Promise.all([asyncWork(1), asyncWork(2)]).then(console.log);

const compose = (...fns) => (value) => fns.reduce((acc, fn) => fn(acc), value);
const addOne = (v) => v + 1;
const double = (v) => v * 2;
console.log(compose(addOne, double)(3));

const assertAssignable = (value) => {
  if (typeof value !== 'string') {
    throw new Error('Expected string');
  }
  return value;
};
console.log(assertAssignable('test'));

const buildConfig = (overrides = {}) => ({
  entry: './src/index.js',
  mode: 'production',
  ...overrides
});
console.log(buildConfig({ mode: 'development' }));

const runTest = (name, fn) => {
  try {
    fn();
    console.log(name, 'passed');
  } catch (error) {
    console.log(name, 'failed', error.message);
  }
};
runTest('example', () => { if (true) return true; });
